class Bell
{
    public string Tone { get; }
    public int Rings { get; private set; }

    public Bell(string tone)
    {
        Tone = tone;
    }

    public void Ring()
    {
        Rings = Rings + 1;
    }
}

class Tower
{
    public int Toll()
    {
        Bell small = new Bell("high");
        small.Ring();
        small.Ring();
        return small.Rings;
    }
}
